import 'dart:convert';
import 'package:http/http.dart' as http;
import '../config/env_config.dart';

/// One delivery window a customer can book.
///
/// Generated by the server from the shop's DELIVERY hours, which are not the same as its
/// opening hours. The app never invents a time or offers a date picker: it shows only
/// what the server says the shop can serve, which is what makes an impossible delivery
/// impossible to order.
class DeliverySlot {
  final DateTime? from;
  final DateTime? until;

  /// "Today", "Tomorrow", or a date, for grouping the list.
  final String dayLabel;

  /// "9:00 AM - 11:00 AM", or "Deliver now" for the express option.
  final String timeLabel;

  /// False when the window is already at the shop's limit. Shown greyed, not hidden,
  /// because seeing that 9 to 11 is full and 11 to 1 is open is useful information.
  final bool available;

  final int booked;
  final int capacity;

  /// The express option: deliver as soon as possible. Carries no window.
  final bool express;

  const DeliverySlot({
    this.from,
    this.until,
    required this.dayLabel,
    required this.timeLabel,
    required this.available,
    this.booked = 0,
    this.capacity = 0,
    this.express = false,
  });

  factory DeliverySlot.fromJson(Map<String, dynamic> json) {
    DateTime? parse(dynamic v) =>
        v == null ? null : DateTime.tryParse(v.toString());

    return DeliverySlot(
      from: parse(json['from']),
      until: parse(json['until']),
      dayLabel: json['dayLabel']?.toString() ?? '',
      timeLabel: json['timeLabel']?.toString() ?? '',
      available: json['available'] == true,
      booked: (json['booked'] as num?)?.toInt() ?? 0,
      capacity: (json['capacity'] as num?)?.toInt() ?? 0,
      express: json['express'] == true,
    );
  }

  /// How the server wants the window back when the order is placed.
  String? get fromIso => from?.toIso8601String();
  String? get untilIso => until?.toIso8601String();
}

class DeliverySlotService {
  static const String _baseUrl = EnvConfig.fullApiUrl;

  /// Windows this shop can still honour.
  ///
  /// Returns an empty list on any failure rather than throwing. Checkout falls back to
  /// an immediate order in that case: a slot lookup failing should never be the reason
  /// a customer cannot buy anything.
  Future<List<DeliverySlot>> getSlots(int shopId) async {
    try {
      final url = Uri.parse('$_baseUrl/orders/shop/$shopId/delivery-slots');
      final response = await http.get(url).timeout(const Duration(seconds: 12));

      if (response.statusCode != 200) return [];

      final data = jsonDecode(response.body);
      final rows = data['data'];
      if (rows is! List) return [];

      return rows
          .whereType<Map<String, dynamic>>()
          .map(DeliverySlot.fromJson)
          .toList();
    } catch (e) {
      print('Failed to load delivery slots: $e');
      return [];
    }
  }
}
